interface ParsedArgs {
  command?: string;
  content: string;
  output: string;
  port: number;
  incremental: boolean;
  clean: boolean;
}

function parseArgs(argv: string[]): ParsedArgs {
  const result: ParsedArgs = {
    command: argv[0],
    content: './content',
    output: './dist',
    port: 3000,
    incremental: false,
    clean: false,
  };
  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--content') {
      result.content = argv[++i] ?? result.content;
    } else if (arg === '--output') {
      result.output = argv[++i] ?? result.output;
    } else if (arg === '--port') {
      const value = Number(argv[++i]);
      if (Number.isFinite(value) && value >= 0) {
        result.port = value;
      }
    } else if (arg === '--incremental') {
      result.incremental = true;
    } else if (arg === '--clean') {
      result.clean = true;
    }
  }
  return result;
}

